head='b7cdbcb015f0a2fc5c2377fa458afcbe67dd944d'; approved='c91d78fd2d90acc198b411aaaf557374f97ca3a5'; incoming='5e657fe01f7e60f752ababde00f9aafd9a4afe4d'
def strip_comments(text):
 result=[]; position=0; depth=0; string=False
 while position<len(text):
  pair=text[position:position+2]; char=text[position]
  if depth:
   if pair=='/-': depth+=1; position+=2
   elif pair=='-/': depth-=1; position+=2; result.append(' ')
   else: position+=1
  elif string:
   result.append(char); position+=1
   if char=='\\\\' and position<len(text): result.append(text[position]); position+=1
   elif char=='\"': string=False
  elif pair=='/-': depth=1; position+=2; result.append(' ')
  elif pair=='--':
   end=text.find('\\n',position); position=len(text) if end<0 else end; result.append(' ')
  else:
   result.append(char); position+=1
   if char=='\"': string=True
 assert depth==0
 return ''.join(result)
changed=git('diff','--name-only',incoming,head,'--','*.lean').splitlines()
unequal=[]
for path in changed:
 before=strip_comments(git('show',incoming+':'+path)); after=strip_comments(git('show',head+':'+path))
 if re.sub(r'\\s+',' ',before).strip()"'!=re.sub(r'"'\\s+',' ',after).strip(): unequal.append(path)
print('Incoming-parent changed Lean files:',len(changed),'non-comment mismatches:',unequal)
base=git('merge-base',approved,incoming).strip(); print('Parent merge base:',base)
incoming_paths=git('diff','--name-only',base,incoming).splitlines()
head_paths=set(git('ls-tree','-r','--name-only',head).splitlines())
print('Incoming changed paths:',len(incoming_paths),'missing from head:',[path for path in incoming_paths if path not in head_paths])
for path in incoming_paths:
 same=git('rev-parse',incoming+':'+path)==git('rev-parse',head+':'+path)
 print('Incoming blob', 'IDENTICAL' if same else 'DIFFERS',path)
for path in git('diff','--name-only',approved,head,'--','*.lean').splitlines():
 prior=strip_comments(git('show',approved+':'+path)); current=strip_comments(git('show',head+':'+path)); source=strip_comments(git('show',incoming+':'+path))
 print('Proof holes',path,[(ref,len(re.findall(r'\\b(?:sorry|admit|axiom)\\b',text))) for ref,text in [('approved',prior),('incoming',source),('head',current)]])
print('Scanner/tests/review integration diff:',git('diff','--name-only',approved,head,'--','scripts','local').strip() or 'none')
